(3, 'Blue Resume', 'Blue gradient styled template with sections for experience, education, skills, mentor and interests.', '/* ===== CSS from Resume1.html ===== */\n* { margin: 0; padding: 0; box-sizing: border-box; }\nbody { font-family: \'Arial\', sans-serif; background-color: #f5f5f5; color: #333; }\n.resume-container { max-width: 800px; margin: 20px auto; background: white; box-shadow: 0 0 20px rgba(0,0,0,0.1); overflow: hidden; }\n\n.header { background: linear-gradient(135deg, #6c5ce7 0%, #a29bfe 100%); color: white; padding: 40px; display: flex; align-items: center; gap: 30px; }\n.profile-image { width: 150px; height: 150px; border-radius: 50%; background: url(\"data:image/svg+xml,<svg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 150 150\'><circle cx=\'75\' cy=\'75\' r=\'75\' fill=\'%23ddd\'/><circle cx=\'75\' cy=\'60\' r=\'20\' fill=\'%23999\'/><path d=\'M75 85c-25 0-45 15-45 35v30h90v-30c0-20-20-35-45-35z\' fill=\'%23999\'/></svg>\") center/cover; border: 4px solid rgba(255,255,255,0.3); flex-shrink: 0; }\n.header-info { flex: 1; }\n.name { font-size: 2.5em; font-weight: bold; color: #ff9500; margin-bottom: 5px; letter-spacing: 1px; }\n.status { font-size: 0.9em; color: rgba(255,255,255,0.8); margin-bottom: 20px; text-transform: uppercase; letter-spacing: 0.5px; }\n\n.resume-section { display: flex; align-items: center; gap: 10px; margin-bottom: 15px; }\n.resume-icon { width: 20px; height: 20px; background: #ff9500; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 12px; }\n.resume-text { font-size: 0.9em; line-height: 1.4; }\n\n.contact-section { background: #f8f9fa; padding: 25px 40px; display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #e0e0e0; }\n.contact-item { text-align: center; font-size: 0.85em; color: #666; }\n.contact-header { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; font-weight: bold; color: #ff9500; text-transform: uppercase; font-size: 0.8em; }\n.contact-icon { width: 16px; height: 16px; background: #ff9500; border-radius: 50%; }\n\n.main-content { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; padding: 40px; }\n.section { margin-bottom: 30px; }\n.section-title { display: flex; align-items: center; gap: 10px; margin-bottom: 20px; padding-bottom: 8px; border-bottom: 2px solid #ff9500; }\n.section-icon { width: 24px; height: 24px; background: #ff9500; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-size: 12px; }\n.section-title h2 { font-size: 1.2em; color: #333; text-transform: uppercase; letter-spacing: 0.5px; }\n\n.experience-item, .education-item { margin-bottom: 20px; padding-left: 20px; position: relative; }\n.experience-item::before, .education-item::before { content: \'\'; position: absolute; left: 0; top: 8px; width: 8px; height: 8px; background: #ff9500; border-radius: 50%; }\n.job-title, .degree-title { font-weight: bold; color: #333; margin-bottom: 2px; }\n.company, .school { font-size: 0.9em; color: #666; margin-bottom: 5px; }\n.description { font-size: 0.85em; line-height: 1.4; color: #555; margin-bottom: 8px; }\n.date { font-size: 0.75em; color: #ff9500; font-weight: bold; }\n\n.skills-section { background: #f8f9fa; padding: 30px 40px; }\n.skills-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 30px; margin-bottom: 30px; }\n.skill-item { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }\n.skill-name { font-weight: bold; color: #333; }\n.skill-bar { width: 120px; height: 8px; background: #e0e0e0; border-radius: 4px; overflow: hidden; }\n.skill-progress { height: 100%; background: linear-gradient(90deg, #ff9500, #ffb347); border-radius: 4px; }\n\n.footer-section { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: start; }\n.mentor-section { background: linear-gradient(135deg, #ff9500, #ffb347); color: white; padding: 20px; border-radius: 8px; }\n.mentor-title { font-size: 1.1em; font-weight: bold; margin-bottom: 10px; }\n.mentor-name { font-size: 1em; margin-bottom: 5px; }\n.mentor-status { font-size: 0.8em; opacity: 0.9; margin-bottom: 5px; }\n.mentor-contact { font-size: 0.8em; opacity: 0.9; }\n\n.interests-section h2 { color: #ff9500; font-size: 1.4em; margin-bottom: 15px; text-transform: uppercase; }\n.interests-list { list-style: none; }\n.interests-list li { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; color: #333; }\n.interests-list li::before { content: \'?\'; color: #ff9500; font-size: 0.8em; }', '<div class=\"resume-container\">\n        <div class=\"header\">\n            <div class=\"profile-image\"></div>\n            <div class=\"header-info\">\n                <h1 class=\"name\">YOUR NAME</h1>\n                <p class=\"status\">YOUR CURRENT STATUS (OR THE ROLE YOU WANT)</p>\n                <div class=\"resume-section\">\n                    <div class=\"resume-icon\">?</div>\n                    <div class=\"resume-text\">\n                        <strong>SUMMARY</strong><br>\n                        Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Quis ipsum suspendisse ultrices gravida. Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore.\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"contact-section\">\n            <div class=\"contact-item\">\n                <div class=\"contact-header\">\n                    <div class=\"contact-icon\"></div>\n                    CONTACT\n                </div>\n                <div>(+237) XXX XXX XXX</div>\n                <div>(+237) XXX XXX XXX</div>\n            </div>\n            <div class=\"contact-item\">\n                <div>www.yourwebsite.com</div>\n                <div>your@email.com</div>\n            </div>\n            <