                 <div class=\"date\">20XX - 20XX</div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"right-column\">\n                <div class=\"section\">\n                    <div class=\"section-title\">\n                        <div class=\"section-icon\">?</div>\n                        <h2>EDUCATION</h2>\n                    </div>\n\n                    <div class=\"education-item\">\n                        <div class=\"degree-title\">DEGREE EARNED</div>\n                        <div class=\"school\">Institution name</div>\n                        <div class=\"description\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do</div>\n                        <div class=\"date\">20XX - 20XX</div>\n                    </div>\n\n                    <div class=\"education-item\">\n                        <div class=\"degree-title\">DEGREE EARNED</div>\n                        <div class=\"school\">Institution name</div>\n                        <div class=\"description\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do</div>\n                        <div class=\"date\">20XX - 20XX</div>\n                    </div>\n\n                    <div class=\"education-item\">\n                        <div class=\"degree-title\">DEGREE EARNED</div>\n                        <div class=\"school\">Institution name</div>\n                        <div class=\"description\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do</div>\n                        <div class=\"date\">20XX - 20XX</div>\n                    </div>\n\n                    <div class=\"education-item\">\n                        <div class=\"degree-title\">DEGREE EARNED</div>\n                        <div class=\"school\">Institution name</div>\n                        <div class=\"description\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do</div>\n                        <div class=\"date\">20XX - 20XX</div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class=\"skills-section\">\n            <div class=\"section-title\">\n                <div class=\"section-icon\">?</div>\n                <h2>EXPERTISE</h2>\n            </div>\n\n            <div class=\"skills-grid\">\n                <div>\n                    <div class=\"skill-item\">\n                        <span class=\"skill-name\">Microsoft Word</span>\n                        <div class=\"skill-bar\"><div class=\"skill-progress\" style=\"width: 85%\"></div></div>\n                    </div>\n                    <div class=\"skill-item\">\n                        <span class=\"skill-name\">Adobe Illustrator</span>\n                        <div class=\"skill-bar\"><div class=\"skill-progress\" style=\"width: 70%\"></div></div>\n                    </div>\n                </div>\n                <div>\n                    <div class=\"skill-item\">\n                        <span class=\"skill-name\">Microsoft PowerPoint</span>\n                        <div class=\"skill-bar\"><div class=\"skill-progress\" style=\"width: 90%\"></div></div>\n                    </div>\n                    <div class=\"skill-item\">\n                        <span class=\"skill-name\">Adobe Photoshop</span>\n                        <div class=\"skill-bar\"><div class=\"skill-progress\" style=\"width: 80%\"></div></div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"footer-section\">\n                <div class=\"mentor-section\">\n                    <div class=\"mentor-title\">YOUR MENTOR</div>\n                    <div class=\"mentor-name\">MICHAEL R. MAGEE</div>\n                    <div class=\"mentor-status\">THEIR CURRENT TITLE</div>\n                    <div class=\"mentor-contact\">(+237) XXX XXX XXX</div>\n                </div>\n\n                <div class=\"interests-section\">\n                    <h2>I