(4, 'Orange Resume', 'Modern orange-styled template using Google Fonts, Font Awesome icons, and a clean grid layout.', '/* ===== CSS from Resume2.html ===== */\n:root{\n  --brand:#f59e0b;          /* orange */\n  --ink:#1f2328;            /* texte */\n  --muted:#6b7280;          /* texte secondaire */\n  --line:#eaecef;           /* séparateurs */\n  --panel:#fafafa;          /* panneaux gris clair */\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:#f3f4f6;color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial}\n\n/* ===== PAGE ===== */\n.sheet{width:210mm; min-height:297mm; background:#fff; margin:16px auto; box-shadow:0 10px 30px rgba(0,0,0,.08); overflow:hidden}\n@media print{body{background:#fff}.sheet{box-shadow:none;margin:0}}\n.wrap{padding:16mm 14mm}\n\n/* ===== HEADER ===== */\n.header{display:grid;grid-template-columns:175px 1fr;gap:18px;align-items:center}\n.portrait{position:relative;width:175px;height:175px;border-radius:50%;overflow:hidden}\n.portrait img{width:100%;height:100%;object-fit:cover}\n/* le croissant blanc sur l\'image */\n.portrait::after{content:\"\";position:absolute;bottom:-6px;left:-6px;width:60%;height:60%;border:10px solid #fff;border-top-color:transparent;border-right-color:transparent;border-bottom-left-radius:140px;transform:rotate(-35deg)}\n\n.title h1{font-family:Poppins,Inter,sans-serif;color:var(--brand);font-size:46px;line-height:1.05;font-weight:800;letter-spacing:.3px;margin:0}\n.title .subtitle{margin-top:3px;color:#9ca3af;text-transform:uppercase;letter-spacing:1.9px;font-weight:700;font-size:12px}\n\n.resume{margin-top:14px;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px 16px}\n.resume .head{display:flex;gap:10px;align-items:center;font-weight:800;text-transform:uppercase;letter-spacing:1.4px}\n.resume .head i{color:var(--brand)}\n.resume p{margin:8px 0 0;color:#4b5563;line-height:1.6}\n\n/* ===== CONTACT BAR ===== */\n.contact{margin-top:14px;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:14px}\n.contact .row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;align-items:center}\n.contact .center{display:flex;flex-direction:column;align-items:center;justify-content:center}\n.contact .center .dot{width:40px;height:40px;border-radius:999px;background:#fff;border:1px solid var(--line);display:grid;place-items:center;color:var(--brand);margin-bottom:8px}\n.contact .item{display:flex;gap:10px;align-items:center;color:#1f2937}\n.contact i{color:var(--brand)}\n\n/* ===== MAIN GRID ===== */\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:16px}\n.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px}\n.panel h2{margin:0 0 12px; text-transform:uppercase; letter-spacing:1.2px; font-size:18px;display:flex;align-items:center;gap:10px}\n.panel h2 i{color:var(--brand)}\n\n.timeline{display:flex;flex-direction:column;gap:14px}\n.item{display:grid;grid-template-columns:14px 1fr;gap:12px}\n.pin{position:relative}\n.pin::before{content:\"\";position:absolute;left:6px;top:0;bottom:-14px;width:2px;background:var(--line)}\n.item:last-child .pin::before{display:none}\n.node{width:12px;height:12px;border-radius:999px;background:var(--brand);display:block;margin-top:4px}\n.role{font-weight:800}\n.org{font-weight:700;color:#6b7280}\n.desc{color:#6b7280;font-size:13px;margin-top:4px}\n.years{color:var(--brand);font-weight:800;font-size:12px;margin-top:6px}\n\n/* ===== EXPERTISE ===== */\n.expert{margin-top:16px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:14px}\n.expert .title{display:flex;align-items:center;gap:10px;justify-content:center;text-transform:uppercase;font-weight:800;letter-spacing:1.6px}\n.expert .title i{color:var(--brand)}\n.skills{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:12px}\n.skill b{font-size:14px}\n.bar{height:6px;background:#f3f4f6;border-radius:999px;overflow:hidden;margin-top:6px;position:relative}\n.bar span{display:block;height:100%;background:var(--brand);width:70%}\n.bar::after{content:\"\";position:absolute;right:-6px;top:50%;transform:translateY(-50%);width:12px;height:12px;border-radius:50%;background:var(--brand)}\n\n/* ===== FOOTER (Mentor / Intérêts) ===== */\n.footer{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:10px}\n.badge{color:var(--brand);font-weight:900;text-transform:uppercase}\n.muted{color:#6b7280}\n', '<section class=\"sheet\">\n    <div class=\"wrap\">\n      <!-- HEADER -->\n      <div class=\"header\">\n        <div class=\"portrait\">\n          <!-- remplacez l\'image -->\n          <img src=\"https://images.unsplash.com/photo-1607746882042-944635dfe10e?q=80&amp;w=600&amp;auto=format&amp;fit=crop\" alt=\"portrait\"/>\n        </div>\n        <div class=\"title\">\n          <h1 data-field=\"name\">YOUR NAME</h1>\n          <div class=\"subtitle\" data-field=\"headline\">YOUR CURRENT STATUS (OR THE ROLE YOU WANT)</div>\n\n          <div class=\"resume\">\n            <div class=\"head\"><i class=\"fa-solid fa-user\"></i> SUMMARY</div>\n            <p data-field=\"summary\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Quis ipsum suspendisse ultrices gravida. Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- CONTACT -->\n      <div class=\"contact\">\n        <div class=\"row\">\n          <div class=\"item\"><i class=\"fa-solid fa-phone\"></i> <span data-field=\"phone1\">(+237) XXX XXX XXX</span></div>\n          <div class=\"center\">\n            <div class=\"dot\"><i class=\"fa-solid fa-circle\"></i></div>\n            <div data-field=\"website\">www.yourwebsite.com</div>\n            <div data-field=\"email\">your@email.com</div>\n          </div>\n          <div class=\"item\" style=\"justify-self:end\"><i class=\"fa-solid fa-location-dot\"></i> <span data-field=\"location\">Street, District - City, Country</span></div>\n        </div>\n      </div>\n\n      <!-- MAIN GRID: EXPERIENCE / EDUCATION -->\n      <div class=\"grid\">\n        <div class=\"panel\">\n          <h2><i class=\"fa-solid fa-briefcase\"></i> WORK EXPERIENCE</h2>\n          <div class=\"timeline\" data-collection=\"experience\">\n            <div class=\"item\">\n              <div class=\"pin\"><span class=\"node\"></span></div>\n              <div>\n                <div class=\"role\" data-field=\"role\">POSITION HELD</div>\n                <div class=\"org\" data-field=\"company\">Company name</div>\n                <div class=\"desc\" data-field=\"summary\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do.</div>\n                <div class=\"years\" data-field=\"dates\">20XX - 20XX</div>\n              </div>\n            </div>\n            <div class=\"item\">\n              <div class=\"pin\"><span class=\"node\"></span></div>\n              <div>\n                <div class=\"role\">POSITION HELD</div>\n                <div class=\"org\">Company name</div>\n                <div class=\"desc\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do.</div>\n                <div class=\"years\">20XX - 20XX</div>\n              </div>\n            </div>\n            <div class=\"item\">\n              <div class=\"pin\"><span class=\"node\"></span></div>\n              <div>\n                <div class=\"role\">POSITION HELD</div>\n                <div class=\"org\">Company name</div>\n                <div class=\"desc\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do.</div>\n                <div class=\"years\">20XX - 20XX</div>\n              </div>\n            </div>\n            <div class=\"item\">\n              <div class=\"pin\"><span class=\"node\"></span></div>\n              <div>\n                <div class=\"role\">POSITION HELD</div>\n                <div class=\"org\">Company name</div>\n                <div class=\"desc\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do.</div>\n                <div class=\"years\">20XX - 20XX</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"panel\">\n          <h2><i class=\"fa-solid fa-graduation-cap\"></i> EDUCATION</h2>\n          <div class=\"timeline\" data-collection=\"education\">\n            <div class=\"item\">\n              <div class=\"pin\"><span class=\"node\"></span></div>\n              <div>\n                <div class=\"role\" data-field=\"degree\">DEGREE EARNED</div>\n                <div class=\"org\" data-field=\"school\">Institution name</div>\n                <div class=\"desc\" data-field=\"notes\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do</div>\n                <div class=\"years\" data-field=\"years\">20XX - 20XX</div>\n              </div>\n            </div>\n            <div class=\"item\">\n              <div class=\"pin\"><span class=\"node\"></span></div>\n              <div>\n                <div class=\"role\">DEGREE EARNED</div>\n                <div class=\"org\">Institution name</div>\n                <div class=\"desc\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do</div>\n                <div class=\"years\">20XX - 20XX</div>\n              </div>\n            </div>\n            <div class=\"item\">\n              <div class=\"pin\"><span class=\"node\"></span></div>\n              <div>\n                <div class=\"role\">DEGREE EARNED</div>\n                <div class=\"org\">Institution name</div>\n                <div class=\"desc\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do</div>\n                <div class=\"years\">20XX - 20XX</div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- EXPERTISE -->\n      <div class=\"expert\">\n        <div class=\"title\"><i class=\"fa-solid fa-lightbulb\"></i> EXPERTISE</div>\n        <div class=\"skills\" data-collection=\"skills\">\n          <div class=\"skill\"><b>Microsoft Word</b><div class=\"bar\"><span style=\"width:78%\"></span></div></div>\n          <div class=\"skill\"><b>Microsoft PowerPoint</b><div class=\"bar\"><span style=\"width:74%\"></span></div></div>\n          <div class=\"skill\"><b>Adobe Illustrator</b><div class=\"bar\"><span style=\"width:62%\"></span></div></div>\n          <div class=\"skill\"><b>Adobe Photoshop</b><div class=\"bar\"><span style=\"width:76%\"></span></div></div>\n        </div>\n      </div>\n\n      <!-- FOOTER: Mentor / Intérêts -->\n      <div class=\"footer\">\n        <div>\n          <div class=\"badge\">Your Mentor</div>\n          <div class=\"muted\" data-field=\"mentor\">MICHAEL R. MAGEE - Their current title - (+237) XXX XXX XXX</div>\n        </div>\n        <div style=\"text-align:right\">\n          <div class=\"badge\">Interests</div>\n          <div class=\"muted\" data-field=\"interests\">TRAVEL ? MUSIC</div>\n        </div>\n      </div>\n    </div>\n  </section>', 1, '2025-09-07 21:39:55'),
(5, 'Two Column Black-Bar \r\n', 'Two-column CV template with black contact bar and right gray sidebar (Education, Languages, Skills).', '/* ===== CSS for Two Column Black-Bar (EN) ===== */\n:root{\n  --ink:#121212;\n  --muted:#60656a;\n  --line:#eaeaea;\n  --panel:#f3f3f3;\n  --black:#111;\n  --accent:#111;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0;background:#fff;color:var(--ink)}\nbody{font:14px/1.6 Inter,system-ui,Segoe UI,Roboto,Arial}\n.sheet{width:210mm; min-height:297mm; margin:16px auto; background:#fff; box-shadow:0 10px 30px rgba(0,0,0,.08); overflow:hidden}\n@media print{body{background:#fff}.sheet{margin:0; box-shadow:none; page-break-after:always}}\n.wrap{padding:18mm 18mm 16mm 18mm}\n.header{display:grid; grid-template-columns:1fr 240px; gap:20px; align-items:start}\n.title small{display:block; color:#8b8f94; letter-spacing:.16em; text-transform:uppercase; margin-top:6px; font-weight:600}\n.title h1{margin:0 0 8px 0; font-family:Poppins,Inter,sans-serif; font-weight:800; font-size:52px; line-height:1.05; letter-spacing:.3px}\n.title h1 .thin{font-weight:600; display:block}\n.photo{width:240px; height:240px; background:#ddd; overflow:hidden; justify-self:end}\n.photo img{width:100%; height:100%; object-fit:cover; display:block}\n.contact{margin-top:16px; background:var(--black); color:#fff; display:grid; grid-template-columns:1fr 1fr 1fr; gap:18px; padding:14px 16px; font-size:13px; font-weight:600}\n.contact b{display:block; opacity:.9; font-weight:700}\n.contact .sub{opacity:.85; font-weight:400; margin-top:4px}\n.grid{margin-top:18px; display:grid; grid-template-columns:1.1fr .9fr; gap:24px}\n.section{margin-top:18px}\n.h{font-family:Poppins,Inter,sans-serif; font-weight:800; letter-spacing:.1em; text-transform:uppercase; font-size:16px; color:var(--accent); border-bottom:2px solid var(--line); padding-bottom:6px; margin-bottom:10px}\n.lead{color:#4b4f54}\n.exp-item{margin:14px 0}\n.role{font-weight:700}\n.org{font-weight:600; color:#444}\n.when{color:#8b8f94; font-weight:700; margin-top:2px; font-size:12px}\n.exp-item p{margin:6px 0 0 0; color:#555}\n.refs{display:grid; grid-template-columns:1fr 1fr; gap:16px}\n.ref b{display:block; font-weight:700}\n.ref .meta{color:#555; font-size:13px}\n.side{background:var(--panel); border:1px solid var(--line); border-radius:4px; padding:16px}\n.side .h{border-color:#dcdcdc}\n.edu-item{margin:10px 0}\n.edu-item .degree{font-weight:700}\n.edu-item .school{color:#555}\n.edu-item .years{color:#8b8f94; font-weight:700; font-size:12px; margin-bottom:2px}\n.bullets{margin:8px 0 0 0; padding-left:16px}\n.bullets li{margin:4px 0}', '<section class=\"sheet\">\n    <div class=\"wrap\">\n      <div class=\"header\">\n        <div class=\"title\">\n          <h1>\n            <span class=\"thin\">FIRST NAME</span>\n            LAST NAME\n          </h1>\n          <small>YOUR CURRENT STATUS</small>\n        </div>\n        <div class=\"photo\">\n          <img src=\"https://images.unsplash.com/photo-1544006659-f0b21884ce1d?q=80&w=800&auto=format&fit=crop\" alt=\"photo\">\n        </div>\n      </div>\n\n      <div class=\"contact\">\n        <div>\n          <b>Phone</b>\n          <div class=\"sub\">+237 XXX XXX<br>+237 XXX XXX</div>\n        </div>\n        <div>\n          <b>Email</b>\n          <div class=\"sub\">yourmail@gmail.com<br>yourwebsite.com</div>\n        </div>\n        <div>\n          <b>Address</b>\n          <div class=\"sub\">Street, District<br>City, Country</div>\n        </div>\n      </div>\n\n      <div class=\"grid\">\n        <div>\n          <div class=\"section\">\n            <div class=\"h\">Profile</div>\n            <p class=\"lead\">Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.</p>\n          </div>\n\n          <div class=\"section\">\n            <div class=\"h\">Experience</div>\n            <div class=\"exp-item\">\n              <div class=\"role\">Job Title</div>\n              <div class=\"org\">Company Name / City</div>\n              <div class=\"when\">Present</div>\n              <p>Lorem Ipsum is simply dummy text of the printing and typesetting industry.</p>\n            </div>\n          </div>\n\n          <div class=\"section\">\n            <div class=\"h\">Mentor or Reference</div>\n            <div class=\"refs\">\n              <div class=\"ref\">\n                <div class=\"meta\">Current Position</div>\n                <b>Full Name</b>\n                <div class=\"meta\">(+237) XXX XXX XXX</div>\n              </div>\n              <div class=\"ref\">\n                <div class=\"meta\">Current Position</div>\n                <b>Full Name</b>\n                <div class=\"meta\">(+237) XXX XXX XXX</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <aside class=\"side\">\n          <div class=\"section\">\n            <div class=\"h\">Education</div>\n            <div class=\"edu-item\">\n              <div class=\"years\">20XX - 20XX</div>\n              <div class=\"degree\">Degree Earned</div>\n              <div class=\"school\">Name of Institution</div>\n            </div>\n          </div>\n\n          <div class=\"section\">\n            <div class=\"h\">Languages</div>\n            <ul class=\"bullets\">\n              <li>English</li>\n              <li>French</li>\n            </ul>\n          </div>\n\n          <div class=\"section\">\n            <div class=\"h\">Skills</div>\n            <ul class=\"bullets\">\n              <li>Photoshop</li>\n              <li>Illustrator</li>\n              <li>InDesign</li>\n            </ul>\n          </div>\n        </aside>\n      </div>\n    </div>\n  </section>', 1, '2025-09-09 11:08:46');
COMMIT;

